var n=`0433-farikal`;var a=`world-0433`;var i=`NO`;var r=`northern-europe`;var o=4;var l=157;var s={en:`Fårikål`,ua:`Форікол`};var g={en:`A traditional dish from Norway, centered on lamb, white cabbage, potato. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Норвегія. Основні складники: ягнятина, білоголова капуста, картопля. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Alternate large pieces of lamb and cabbage in a deep pot, seasoning each layer with salt and whole peppercorns.`,ua:`У глибокій каструлі чергуйте великі шматки баранини й капусти, приправляючи кожен шар сіллю та цілим перцем.`,t:[`layered-assembly`],m:10,i:[[`lamb`,950,`g`],[`white-cabbage`,900,`g`],[`black-peppercorn`,8,`g`],[`table-salt`,14,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 125 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 125 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:125,i:[[`water`,550,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 22 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 22 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:22,i:[[`potato`,500,`g`]]}];var m={slug:n,id:a,country:`NO`,region:r,servings:4,minutes:157,title:s,text:g,steps:d};export{i as country,m as default,a as id,l as minutes,r as region,o as servings,n as slug,d as steps,g as text,s as title};